class UeUnreachable(UeManagerException):
    """Can not connect to ue after many reboot"""

    def __init__(self, ue_sn, reboots):
        """

        :param ue_sn: UE serial number
        :param reboots: number of reboots before raise
        """
        super().__init__()
        self.ue_sn = ue_sn
        self.reboots = int(reboots)

    def __str__(self):
        return f"Can not connect to UE {self.ue_sn} after {self.reboots} reboots"

